# Use Node.js to unzip and parse the docx XML
node -e "
const fs = require('fs');
const zlib = require('zlib');
const { execSync } = require('child_process');

// Use unzip if available, otherwise manually parse the zip
try {
  execSync('which unzip');
} catch(e) {}

const tmpDir = '/tmp/docx_extract';
fs.mkdirSync(tmpDir, { recursive: true });
execSync('cd /tmp/docx_extract && unzip -o /workspace/testbed/docs/customer_report.docx 2>/dev/null || true');

if (fs.existsSync(tmpDir + '/word/document.xml')) {
  const xml = fs.readFileSync(tmpDir + '/word/document.xml', 'utf8');
  // Extract text between <w:t> tags
  const matches = xml.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
  let currentParagraph = '';
  const paragraphs = [];

  // Split by paragraph markers
  const parts = xml.split(/<w:p[ >\/]/);
  for (const part of parts) {
    const texts = [];
    const tMatches = part.match(/<w:t[^>]*>([^<]*)<\/w:t>/g) || [];
    for (const m of tMatches) {
      const text = m.replace(/<w:t[^>]*>/, '').replace(/<\/w:t>/, '');
      texts.push(text);
    }
    if (texts.length > 0) {
      paragraphs.push(texts.join(''));
    }
  }
  console.log(paragraphs.join('\n'));
} else {
  console.error('Could not extract document.xml');
}
"

# No unzip available — use Node.js built-in zlib to manually parse the ZIP file
node -e "
const fs = require('fs');
const zlib = require('zlib');
const buf = fs.readFileSync('/workspace/testbed/docs/customer_report.docx');

// Parse ZIP format manually to find word/document.xml
let offset = 0;
while (offset < buf.length - 4) {
  const sig = buf.readUInt32LE(offset);
  if (sig !== 0x04034b50) break; // Local file header signature

  const compMethod = buf.readUInt16LE(offset + 8);
  const compSize = buf.readUInt32LE(offset + 18);
  const uncompSize = buf.readUInt32LE(offset + 22);
  const fnLen = buf.readUInt16LE(offset + 26);
  const extraLen = buf.readUInt16LE(offset + 28);
  const fileName = buf.toString('utf8', offset + 30, offset + 30 + fnLen);
  const dataStart = offset + 30 + fnLen + extraLen;
  const rawData = buf.slice(dataStart, dataStart + compSize);

  if (fileName === 'word/document.xml') {
    let content;
    if (compMethod === 0) {
      content = rawData.toString('utf8');
    } else {
      content = zlib.inflateRawSync(rawData).toString('utf8');
    }
    // Parse paragraphs
    const parts = content.split(/<\/w:p>/);
    for (const part of parts) {
      const texts = [];
      const re = /<w:t[^>]*>([^<]*)<\/w:t>/g;
      let m;
      while ((m = re.exec(part)) !== null) {
        texts.push(m[1]);
      }
      if (texts.length > 0) {
        console.log(texts.join(''));
      }
    }
    break;
  }
  offset = dataStart + compSize;
}
"
